// Assuming Shodan data is in $json, and CVEs are in data.vulns
let cveList = [];
const shodanData = $json; 

// Shodan's vulnerability data is often nested or listed in a 'vulns' array
if (shodanData.vulns && Array.isArray(shodanData.vulns)) {
  // Add all discovered CVEs from the Shodan report
  cveList.push(...shodanData.vulns); 
}

// Only pass items if CVEs were found
if (cveList.length > 0) {
    return cveList.map(cve => ({ 
        json: { 
            cve_id: cve.toUpperCase() // CISA KEV requires uppercase CVE
        }
    }));
} 
// If no CVEs are found by Shodan, return no items to stop the CISA branch
return [];

const waybackData = $json;
const snapshots = [];

// The first array is the column header, so skip it (if using output=json)
for (let i = 1; i < waybackData.length; i++) {
  const [urlkey, timestamp, original, mimetype, statuscode, digest, length] = waybackData[i];

  // Only include successful captures (status 200) and redirects (status 3xx)
  if (statuscode.startsWith('2')) {
    snapshots.push({
      timestamp: timestamp,
      original_url: original,
      status_code: statuscode,
      archive_link: `http://web.archive.org/web/${timestamp}/${original}`
    });
  }
}

return [{ json: {
    wayback_snapshots: snapshots,
    total_snapshots: snapshots.length
}}];

const rawHeaders = $json.data; // Assuming the raw text response is in $json.data

// Split the raw text into individual lines
const lines = rawHeaders.trim().split('\n');

const results = {};
const headers = {};
let redirectChain = [];

// Parse each line
for (const line of lines) {
    if (line.includes('Redirect:')) {
        // Collect redirect steps
        const redirectUrl = line.split('Redirect:')[1].trim();
        redirectChain.push(redirectUrl);
    } else if (line.includes(': ')) {
        // Collect individual headers
        const [key, value] = line.split(': ', 2);
        headers[key.trim()] = value.trim();
    }
}

// Add the final, processed data to the output
results.headers = headers;
results.redirect_chain = redirectChain;
results.final_destination = redirectChain.length > 0 ? redirectChain[redirectChain.length - 1] : $json.ioc_value;

// Evaluate key security headers
results.security_score = {
    'HSTS_Present': headers['Strict-Transport-Security'] ? 'YES' : 'NO',
    'X_Frame_Options_Present': headers['X-Frame-Options'] ? 'YES' : 'NO',
    'CSP_Present': headers['Content-Security-Policy'] ? 'YES' : 'NO'
};

return [{ json: results }];

